using namespace std;

int main() {
    int n, k;
    string s;
    cin >> n >> k >> s;

    sort(s.begin(), s.end());

    int sum = 0, count = 0;
    char last = 0;

    for (char c : s) {
        if (count == 0 || c - last > 1) {
            sum += c - 'a' + 1;
            last = c;
            count++;
            if (count == k) break;
        }
    }

    cout << (count == k ? sum : -1) << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

vector<int> v;
int cont = 0, sum = 0;
int n, k;

void fun(int i) {
    int currV = v[i];
    sum = currV;
    cont = 1;

    for (i++; i < (int)v.size(); i++) {
        if (cont == k) return;
        if (v[i] - currV > 1) {
            sum += v[i];
            currV = v[i];
            cont++;
        }
    }
}

int main() {
    string s;
    cin >> n >> k >> s;

    sort(s.begin(), s.end());

    for (char c : s) {
        v.push_back(c - 'a' + 1);
    }

    int ans = INT_MAX;

    for (int i = 0; i < (int)v.size(); i++) {
        fun(i);
        if (cont == k) {
            ans = min(ans, sum);
        }
    }

    cout << (ans == INT_MAX ? -1 : ans) << '\n';
    return 0;
}

