int main() {
    int n, k;
    string s;
    cin >> n >> k >> s;

    sort(s.begin(), s.end());

    int answer = INT_MAX;

    for (int start = 0; start < n; ++start) {
        int sum = s[start] - 'a' + 1;
        int count = 1;
        char last = s[start];

        for (int i = start + 1; i < n && count < k; ++i) {
            if (s[i] - last > 1) {
                sum += s[i] - 'a' + 1;
                last = s[i];
                ++count;
            }
        }

        if (count == k)
            answer = min(answer, sum);
    }

    cout << (answer == INT_MAX ? -1 : answer) << '\n';
    return 0;
}

